mapper.select:
SELECT id, order_no, customer_id, contact_id, contract_id, total_amount, status, remark,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_order
WHERE organization_id = #{organizationId}

    AND (order_no LIKE CONCAT('%', #{keyword}, '%') OR remark LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND customer_id = #{customerId}

ORDER BY create_time DESC
